-- READ-ONLY aggregate; exact-key source rows absent from reconstruction. UTC fixed bounds.
WITH c AS (SELECT CASE WHEN o.dateTime < 1293840000 THEN 2010 ELSE 2011 END AS utc_year, o.usUnits AS ou, w.usUnits AS wu, o.interval AS oi, w.interval AS wi, o.`extraTemp3` AS old_extraTemp3, w.`extraTemp3` AS wh_extraTemp3, o.`extraTemp4` AS old_extraTemp4, w.`extraTemp4` AS wh_extraTemp4, o.`hail` AS old_hail, w.`hail` AS wh_hail, o.`hailRate` AS old_hailRate, w.`hailRate` AS wh_hailRate, o.`heatindex` AS old_heatindex, w.`heatindex` AS wh_heatindex, o.`heatingTemp` AS old_heatingTemp, w.`heatingTemp` AS wh_heatingTemp, o.`heatingVoltage` AS old_heatingVoltage, w.`heatingVoltage` AS wh_heatingVoltage, o.`inHumidity` AS old_inHumidity, w.`inHumidity` AS wh_inHumidity, o.`inTemp` AS old_inTemp, w.`inTemp` AS wh_inTemp, o.`inTempBatteryStatus` AS old_inTempBatteryStatus, w.`inTempBatteryStatus` AS wh_inTempBatteryStatus
FROM old_weewx.archive o JOIN weewx_WH1080.archive w ON w.dateTime=o.dateTime LEFT JOIN loucka_reconstruction.archive r ON r.dateTime=o.dateTime
WHERE o.dateTime >= 1262304000 AND o.dateTime < 1325376000 AND r.dateTime IS NULL)
SELECT utc_year, 'extraTemp3' AS field_name, COUNT(*) AS source_only_rows, SUM(old_extraTemp3 IS NOT NULL) AS old_nonnull, SUM(wh_extraTemp3 IS NOT NULL) AS wh_nonnull, SUM(old_extraTemp3 IS NOT NULL AND wh_extraTemp3 IS NOT NULL AND old_extraTemp3 <=> wh_extraTemp3) AS paired_equal, SUM(old_extraTemp3 IS NOT NULL AND wh_extraTemp3 IS NOT NULL AND NOT(old_extraTemp3 <=> wh_extraTemp3)) AS paired_conflict, SUM(ou <> wu) AS unit_conflict_rows, SUM(oi <> wi) AS interval_conflict_rows FROM c GROUP BY utc_year UNION ALL
SELECT utc_year, 'extraTemp4' AS field_name, COUNT(*) AS source_only_rows, SUM(old_extraTemp4 IS NOT NULL) AS old_nonnull, SUM(wh_extraTemp4 IS NOT NULL) AS wh_nonnull, SUM(old_extraTemp4 IS NOT NULL AND wh_extraTemp4 IS NOT NULL AND old_extraTemp4 <=> wh_extraTemp4) AS paired_equal, SUM(old_extraTemp4 IS NOT NULL AND wh_extraTemp4 IS NOT NULL AND NOT(old_extraTemp4 <=> wh_extraTemp4)) AS paired_conflict, SUM(ou <> wu) AS unit_conflict_rows, SUM(oi <> wi) AS interval_conflict_rows FROM c GROUP BY utc_year UNION ALL
SELECT utc_year, 'hail' AS field_name, COUNT(*) AS source_only_rows, SUM(old_hail IS NOT NULL) AS old_nonnull, SUM(wh_hail IS NOT NULL) AS wh_nonnull, SUM(old_hail IS NOT NULL AND wh_hail IS NOT NULL AND old_hail <=> wh_hail) AS paired_equal, SUM(old_hail IS NOT NULL AND wh_hail IS NOT NULL AND NOT(old_hail <=> wh_hail)) AS paired_conflict, SUM(ou <> wu) AS unit_conflict_rows, SUM(oi <> wi) AS interval_conflict_rows FROM c GROUP BY utc_year UNION ALL
SELECT utc_year, 'hailRate' AS field_name, COUNT(*) AS source_only_rows, SUM(old_hailRate IS NOT NULL) AS old_nonnull, SUM(wh_hailRate IS NOT NULL) AS wh_nonnull, SUM(old_hailRate IS NOT NULL AND wh_hailRate IS NOT NULL AND old_hailRate <=> wh_hailRate) AS paired_equal, SUM(old_hailRate IS NOT NULL AND wh_hailRate IS NOT NULL AND NOT(old_hailRate <=> wh_hailRate)) AS paired_conflict, SUM(ou <> wu) AS unit_conflict_rows, SUM(oi <> wi) AS interval_conflict_rows FROM c GROUP BY utc_year UNION ALL
SELECT utc_year, 'heatindex' AS field_name, COUNT(*) AS source_only_rows, SUM(old_heatindex IS NOT NULL) AS old_nonnull, SUM(wh_heatindex IS NOT NULL) AS wh_nonnull, SUM(old_heatindex IS NOT NULL AND wh_heatindex IS NOT NULL AND old_heatindex <=> wh_heatindex) AS paired_equal, SUM(old_heatindex IS NOT NULL AND wh_heatindex IS NOT NULL AND NOT(old_heatindex <=> wh_heatindex)) AS paired_conflict, SUM(ou <> wu) AS unit_conflict_rows, SUM(oi <> wi) AS interval_conflict_rows FROM c GROUP BY utc_year UNION ALL
SELECT utc_year, 'heatingTemp' AS field_name, COUNT(*) AS source_only_rows, SUM(old_heatingTemp IS NOT NULL) AS old_nonnull, SUM(wh_heatingTemp IS NOT NULL) AS wh_nonnull, SUM(old_heatingTemp IS NOT NULL AND wh_heatingTemp IS NOT NULL AND old_heatingTemp <=> wh_heatingTemp) AS paired_equal, SUM(old_heatingTemp IS NOT NULL AND wh_heatingTemp IS NOT NULL AND NOT(old_heatingTemp <=> wh_heatingTemp)) AS paired_conflict, SUM(ou <> wu) AS unit_conflict_rows, SUM(oi <> wi) AS interval_conflict_rows FROM c GROUP BY utc_year UNION ALL
SELECT utc_year, 'heatingVoltage' AS field_name, COUNT(*) AS source_only_rows, SUM(old_heatingVoltage IS NOT NULL) AS old_nonnull, SUM(wh_heatingVoltage IS NOT NULL) AS wh_nonnull, SUM(old_heatingVoltage IS NOT NULL AND wh_heatingVoltage IS NOT NULL AND old_heatingVoltage <=> wh_heatingVoltage) AS paired_equal, SUM(old_heatingVoltage IS NOT NULL AND wh_heatingVoltage IS NOT NULL AND NOT(old_heatingVoltage <=> wh_heatingVoltage)) AS paired_conflict, SUM(ou <> wu) AS unit_conflict_rows, SUM(oi <> wi) AS interval_conflict_rows FROM c GROUP BY utc_year UNION ALL
SELECT utc_year, 'inHumidity' AS field_name, COUNT(*) AS source_only_rows, SUM(old_inHumidity IS NOT NULL) AS old_nonnull, SUM(wh_inHumidity IS NOT NULL) AS wh_nonnull, SUM(old_inHumidity IS NOT NULL AND wh_inHumidity IS NOT NULL AND old_inHumidity <=> wh_inHumidity) AS paired_equal, SUM(old_inHumidity IS NOT NULL AND wh_inHumidity IS NOT NULL AND NOT(old_inHumidity <=> wh_inHumidity)) AS paired_conflict, SUM(ou <> wu) AS unit_conflict_rows, SUM(oi <> wi) AS interval_conflict_rows FROM c GROUP BY utc_year UNION ALL
SELECT utc_year, 'inTemp' AS field_name, COUNT(*) AS source_only_rows, SUM(old_inTemp IS NOT NULL) AS old_nonnull, SUM(wh_inTemp IS NOT NULL) AS wh_nonnull, SUM(old_inTemp IS NOT NULL AND wh_inTemp IS NOT NULL AND old_inTemp <=> wh_inTemp) AS paired_equal, SUM(old_inTemp IS NOT NULL AND wh_inTemp IS NOT NULL AND NOT(old_inTemp <=> wh_inTemp)) AS paired_conflict, SUM(ou <> wu) AS unit_conflict_rows, SUM(oi <> wi) AS interval_conflict_rows FROM c GROUP BY utc_year UNION ALL
SELECT utc_year, 'inTempBatteryStatus' AS field_name, COUNT(*) AS source_only_rows, SUM(old_inTempBatteryStatus IS NOT NULL) AS old_nonnull, SUM(wh_inTempBatteryStatus IS NOT NULL) AS wh_nonnull, SUM(old_inTempBatteryStatus IS NOT NULL AND wh_inTempBatteryStatus IS NOT NULL AND old_inTempBatteryStatus <=> wh_inTempBatteryStatus) AS paired_equal, SUM(old_inTempBatteryStatus IS NOT NULL AND wh_inTempBatteryStatus IS NOT NULL AND NOT(old_inTempBatteryStatus <=> wh_inTempBatteryStatus)) AS paired_conflict, SUM(ou <> wu) AS unit_conflict_rows, SUM(oi <> wi) AS interval_conflict_rows FROM c GROUP BY utc_year
ORDER BY utc_year, field_name;
